ALTER TABLE "ai_draft_work" ADD CONSTRAINT "ai_draft_work_effect_state" CHECK (("ai_draft_work"."state" IN ('claimed','failed_before_request') AND "ai_draft_work"."request_started_at" IS NULL AND "ai_draft_work"."draft_id" IS NULL AND "ai_draft_work"."approval_id" IS NULL AND "ai_draft_work"."post_id" IS NULL) OR ("ai_draft_work"."state" IN ('requesting','unknown') AND "ai_draft_work"."request_started_at" IS NOT NULL AND "ai_draft_work"."draft_id" IS NULL AND "ai_draft_work"."approval_id" IS NULL AND "ai_draft_work"."post_id" IS NULL) OR ("ai_draft_work"."state"='succeeded' AND "ai_draft_work"."request_started_at" IS NOT NULL AND (("ai_draft_work"."draft_id" IS NOT NULL AND "ai_draft_work"."approval_id" IS NULL AND "ai_draft_work"."post_id" IS NULL) OR ("ai_draft_work"."kind"='renewal' AND "ai_draft_work"."draft_id" IS NULL AND "ai_draft_work"."approval_id" IS NOT NULL AND "ai_draft_work"."post_id" IS NULL) OR ("ai_draft_work"."kind"='board' AND "ai_draft_work"."draft_id" IS NULL AND "ai_draft_work"."approval_id" IS NULL AND "ai_draft_work"."post_id" IS NOT NULL))));